export const id=()=>crypto.randomUUID();
export function normalizePath(path){return path.replace(/^\/+|\/+$/g,'').replace(/\/+/g,'/');}
export function parentPath(path){const p=normalizePath(path);return p.includes('/')?p.slice(0,p.lastIndexOf('/')):''}
export function basename(path){return normalizePath(path).split('/').pop()}
export function createFile(project,path,content=''){path=normalizePath(path); if(!path||project.files.some(f=>f.path===path))throw Error('A file already exists at that path.'); ensureDirs(project,parentPath(path)); project.files.push({id:id(),path,content,updatedAt:Date.now()}); return project;}
export function createDirectory(project,path){path=normalizePath(path); if(!path||project.directories.includes(path)||project.files.some(f=>f.path===path))throw Error('A file or folder already exists at that path.'); ensureDirs(project,parentPath(path));project.directories.push(path);return project;}
export function ensureDirs(project,path){let at='';for(const part of normalizePath(path).split('/').filter(Boolean)){at=at?at+'/'+part:part;if(!project.directories.includes(at))project.directories.push(at)}}
export function removeEntry(project,path){path=normalizePath(path);const file=project.files.find(f=>f.path===path);if(file){project.files=project.files.filter(f=>f!==file);return project}const exists=project.directories.includes(path);if(!exists)throw Error('Item was not found.'); project.directories=project.directories.filter(d=>d!==path&&!d.startsWith(path+'/'));project.files=project.files.filter(f=>!f.path.startsWith(path+'/'));return project;}
export function renameEntry(project,oldPath,newPath){oldPath=normalizePath(oldPath);newPath=normalizePath(newPath);if(!newPath||project.files.some(f=>f.path===newPath)||project.directories.includes(newPath))throw Error('That destination already exists.'); const file=project.files.find(f=>f.path===oldPath);if(file){ensureDirs(project,parentPath(newPath));file.path=newPath;file.updatedAt=Date.now();return project}if(!project.directories.includes(oldPath))throw Error('Item was not found.');ensureDirs(project,parentPath(newPath));project.directories=project.directories.map(d=>d===oldPath?newPath:d.startsWith(oldPath+'/')?newPath+d.slice(oldPath.length):d);project.files.forEach(f=>{if(f.path.startsWith(oldPath+'/'))f.path=newPath+f.path.slice(oldPath.length)});return project;}
